import csv
import io
import re


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        if csv.field_size_limit() != previous_limit:
            csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = records[1:]
    width = len(columns)
    normalized = [name.strip().lower() for name in columns]
    expected = [
        "file", "truth", "pred", "confidence", "correct",
        "crop_correct", "leaf_pct", "inference_ms", "preprocess_ms",
    ]

    if normalized == expected:
        known_labels = set()
        for row in rows:
            if len(row) == width:
                known_labels.update(row[1:3])

        number = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")

        def plausible_suffix(fields):
            return (
                len(fields) == 6
                and bool(number.fullmatch(fields[0].strip()))
                and fields[1].strip().lower() in ("true", "false")
                and fields[2].strip().lower() in ("true", "false")
                and all(number.fullmatch(value.strip()) for value in fields[3:])
            )

        for i, row in enumerate(rows):
            if len(row) <= width or not plausible_suffix(row[-6:]):
                continue
            middle = row[1:-6]
            candidates = []
            for split in range(1, len(middle)):
                truth = ",".join(middle[:split])
                pred = ",".join(middle[split:])
                score = (
                    3 * (truth in known_labels)
                    + 3 * (pred in known_labels)
                    + ("___" in truth)
                    + ("___" in pred)
                )
                candidates.append((score, truth, pred))
            if candidates:
                best_score = max(candidate[0] for candidate in candidates)
                best = [candidate for candidate in candidates if candidate[0] == best_score]
                if best_score > 0 and len(best) == 1:
                    rows[i] = [row[0], best[0][1], best[0][2]] + row[-6:]

    final_width = max([width] + [len(row) for row in rows])
    existing = set(columns)
    extra_number = 1
    while len(columns) < final_width:
        name = "extra_" + str(extra_number)
        extra_number += 1
        if name not in existing:
            columns.append(name)
            existing.add(name)

    rows = [row + [""] * (final_width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
